-- Wintaskly — blog, articles d'actualite EN ATTENTE
-- Ces deux articles decrivent la plateforme elle-meme. Ils sont crees
-- en brouillon SANS date de parution : relisez-les, ajustez le contenu
-- a ce qui aura ete reellement deploye, puis passez-les en 'published'
-- avec la date voulue depuis l'administration.

-- NOTE : la categorie est resolue par son slug et non par un id fige.
-- Les identifiants de blog_categories peuvent differer d'une base a
-- l'autre ; un id code en dur rangerait l'article dans la mauvaise
-- categorie, ou dans aucune.

INSERT INTO `blog_posts` (`slug`,`category_id`,`title`,`excerpt`,`body`,`cover_emoji`,`author_name`,`meta_title`,`meta_description`,`status`,`reading_minutes`,`published_at`)
SELECT 'ce-qui-a-change-ce-mois-ci',(SELECT `id` FROM `blog_categories` WHERE `slug`='actualites' LIMIT 1),'Ce qui a changé sur Wintaskly ce mois-ci','Corrections et nouveautés, sans filtre. Y compris ce qui n\'a pas bougé, et pourquoi nous le précisons.','<p>Nous publions chaque mois ce qui a été corrigé, ajouté ou modifié. Sans filtre : les corrections de bugs y figurent au même titre que les nouveautés, parce qu\'un site qui n\'annonce que des bonnes nouvelles ne dit pas la vérité.</p>\n\n<h2>Affichage des retraits : une conversion corrigée</h2>\n\n<p>Le montant que vous alliez recevoir ne se mettait plus à jour en direct dès lors qu\'une adresse de paiement était enregistrée. La devise affichée restait figée sur une valeur par défaut, et la conversion ne se recalculait pas pendant la saisie.</p>\n\n<p>La cause était une erreur dans le code de la page. Les demandes de retrait, elles, étaient bien traitées avec le bon montant : c\'était l\'aperçu qui était muet, pas le paiement. Corrigé.</p>\n\n<h2>Adresses de paiement : la réutilisation devient possible</h2>\n\n<p>Utiliser le même identifiant pour deux monnaies — le même compte pour recevoir en bitcoin et en tron, par exemple — se heurtait à un message d\'erreur peu clair.</p>\n\n<p>Désormais, un écran vous signale simplement que cette adresse est déjà enregistrée ailleurs, affiche l\'adresse en entier et vous demande de confirmer. C\'est une relecture, pas un refus : une faute de frappe recopiée reste une faute de frappe, et c\'est le dernier moment où elle ne coûte rien.</p>\n\n<h2>Une méthode sans adresse ne se valide plus</h2>\n\n<p>Si vous choisissiez un moyen de paiement pour lequel vous n\'aviez enregistré aucune adresse, le champ disparaissait sans explication. Vous pouviez saisir un montant, valider, et récupérer une erreur générique.</p>\n\n<p>Le bouton est maintenant inactif dans ce cas, avec un message et un lien direct vers la gestion de vos adresses.</p>\n\n<h2>Courriels de sécurité : dire ce qui se passe</h2>\n\n<p>Deux changements qui paraissent mineurs et ne le sont pas.</p>\n\n<p>Le courriel envoyé pour confirmer une adresse de paiement s\'intitulait « code de connexion ». Il annonce désormais clairement son objet. La différence est décisive : si vous recevez ce message sans avoir rien demandé, vous savez immédiatement que quelqu\'un tente de détourner vos retraits — ce qu\'un intitulé vague ne vous aurait pas dit.</p>\n\n<p>Nos alertes de connexion, ensuite, indiquaient seulement qu\'une « activité notable » avait été détectée. Elles précisent maintenant la date et l\'adresse IP, c\'est-à-dire les seuls éléments qui vous permettent de savoir si c\'était bien vous.</p>\n\n<h2>Un blog qui publie tous les jours ouvrés</h2>\n\n<p>Vous lisez le résultat d\'une décision prise ce mois-ci : un article par jour ouvré, sur des sujets choisis à partir des questions que vous nous posez réellement.</p>\n\n<p>Les catégories Finance et Crypto, jusqu\'ici vides, sont désormais alimentées. Nous y traitons notamment la fiscalité, sujet sur lequel beaucoup d\'articles en ligne affirment des choses fausses avec assurance.</p>\n\n<h2>Ce qui n\'a pas changé</h2>\n\n<p>Le taux de conversion des coins. Les règles de rémunération des tâches. Les seuils de retrait.</p>\n\n<p>Nous le précisons volontairement : quand une plateforme publie une liste de nouveautés, la question légitime est de savoir ce qui a bougé sans être annoncé. Rien, ce mois-ci, du côté de ce que vous gagnez.</p>\n\n<h2>Ce sur quoi nous travaillons</h2>\n\n<p>De nouvelles méthodes de retrait, dont une en euros qui ne dépend d\'aucun cours de crypto. Nous y consacrons un article séparé, parce que la raison de ce choix mérite plus de deux lignes.</p>\n\n<p>Si vous constatez un comportement anormal, signalez-le. Une bonne part des corrections de ce mois vient de messages de membres.</p>\n','📰','Équipe Wintaskly','Ce qui a changé sur Wintaskly ce mois-ci','Corrections et nouveautés, sans filtre. Y compris ce qui n\'a pas bougé, et pourquoi nous le précisons.','draft',6,NULL
 WHERE NOT EXISTS (SELECT 1 FROM (SELECT 1) x WHERE EXISTS (SELECT 1 FROM `blog_posts` WHERE `slug`='ce-qui-a-change-ce-mois-ci'));

INSERT INTO `blog_posts` (`slug`,`category_id`,`title`,`excerpt`,`body`,`cover_emoji`,`author_name`,`meta_title`,`meta_description`,`status`,`reading_minutes`,`published_at`)
SELECT 'nouvelles-methodes-de-retrait',(SELECT `id` FROM `blog_categories` WHERE `slug`='actualites' LIMIT 1),'Nouvelles méthodes de retrait : ce qui arrive et pourquoi','Une réponse à une fragilité de notre propre fonctionnement, et un engagement que nous prenons.','<p>Nous préparons l\'ajout de méthodes de retrait libellées en euros. Ce n\'est pas une simple case supplémentaire : c\'est une réponse à une fragilité que nous avons identifiée dans notre propre fonctionnement.</p>\n\n<h2>Le problème que personne ne voit venir</h2>\n\n<p>Aujourd\'hui, la quasi-totalité de nos méthodes de retrait sont des cryptomonnaies. Convertir vos coins vers une crypto suppose de connaître son cours du moment, que nous récupérons auprès d\'une source extérieure.</p>\n\n<p>Si cette source devient indisponible — panne, changement d\'interface, blocage réseau — nous ne pouvons plus calculer le montant à payer. Et plutôt que de payer un montant faux, le système refuse la demande.</p>\n\n<p>C\'est le bon comportement. Mais si <em>toutes</em> vos options dépendent d\'un cours, une seule panne suffit à bloquer l\'ensemble des retraits. Un site de gains dont personne ne peut retirer n\'est plus un site de gains.</p>\n\n<h2>La solution : une méthode qui ne dépend d\'aucun cours</h2>\n\n<p>L\'euro est notre unité de référence interne. Un retrait libellé en euros ne demande aucune conversion, donc aucune source extérieure. Il fonctionne même si tout le reste est indisponible.</p>\n\n<p>C\'est la raison principale de ce chantier. Pas le confort, la résilience.</p>\n\n<h2>Ce qui est prévu</h2>\n\n<p>Deux méthodes, avec des usages différents.</p>\n\n<p><strong>Un service de paiement en ligne</strong>, pour des montants modestes, avec un seuil bas et un délai court. C\'est ce qui remplacera le plus naturellement un retrait crypto pour ceux qui convertissent aussitôt en euros.</p>\n\n<p><strong>Un virement bancaire</strong>, pour des montants plus importants. Ses frais fixes imposent un seuil nettement plus élevé : sortir dix euros par virement n\'aurait aucun sens économique.</p>\n\n<h2>Pourquoi les seuils diffèrent autant</h2>\n\n<p>Chaque envoi coûte, et ce coût ne dépend pas du montant. Un seuil élevé n\'est pas une façon de retenir votre argent : c\'est le reflet honnête de ce que l\'opération coûte.</p>\n\n<p>Nous préférons afficher un seuil réaliste plutôt qu\'un seuil attractif compensé par une commission discrète prélevée au passage.</p>\n\n<h2>Ce que cela ne change pas</h2>\n\n<p>Le taux de conversion des coins reste identique. Vos coins ne valent pas plus ni moins selon la méthode choisie : seuls changent les frais d\'envoi et le seuil minimum.</p>\n\n<p>Les méthodes crypto existantes ne disparaissent pas. Pour de petits retraits fréquents, un réseau bon marché reste souvent le choix le plus économique.</p>\n\n<h2>Le calendrier, honnêtement</h2>\n\n<p>Ces méthodes apparaîtront dans votre espace de retrait quand elles seront opérationnelles, et pas avant. Nous ne les annonçons pas avec une date parce que leur mise en service dépend de vérifications qui ne dépendent pas entièrement de nous.</p>\n\n<p>Vous les verrez apparaître dans la liste : c\'est le signal qu\'elles sont utilisables. Nous ne proposerons pas une option qui échouerait à la première demande.</p>\n\n<h2>Une garantie de méthode</h2>\n\n<p>Nous maintiendrons toujours au moins une méthode de retrait qui ne dépend d\'aucune source extérieure de cotation.</p>\n\n<p>C\'est une règle interne, et elle a une conséquence concrète : quoi qu\'il arrive à un fournisseur de cours ou à un réseau donné, il restera un chemin pour sortir vos gains. C\'est le genre d\'engagement qui ne se voit jamais tant que tout va bien.</p>\n','🏦','Équipe Wintaskly','Nouvelles méthodes de retrait : ce qui arrive et pourquoi','Une réponse à une fragilité de notre propre fonctionnement, et un engagement que nous prenons.','draft',6,NULL
 WHERE NOT EXISTS (SELECT 1 FROM (SELECT 1) x WHERE EXISTS (SELECT 1 FROM `blog_posts` WHERE `slug`='nouvelles-methodes-de-retrait'));

